const waiting = new Map();

function waitForConfirmation(orderId) {
  const { promise, resolve } = Promise.withResolvers();
  waiting.set(orderId, resolve);
  return promise.finally(() => waiting.delete(orderId));
}

function onWebhook(orderId, ref) {
  waiting.get(orderId)?.(ref);
}

setTimeout(() => onWebhook(7, "PSK_81"), 10);
const ref = await waitForConfirmation(7);
console.log("confirmed:", ref, "still waiting:", waiting.size);
